import { setupServer } from "msw/node"
import { http, HttpResponse } from "msw"

export const handlers = [
  http.get("/api/users", () => HttpResponse.json([{ id: 1, name: "Dinh" }])),
]
export const server = setupServer(...handlers)

// setup file
beforeAll(() => server.listen({ onUnhandledRequest: "error" }))
afterEach(() => server.resetHandlers())   // undo per-test overrides
afterAll(() => server.close())

it("shows an error message when the API fails", async () => {
  server.use(http.get("/api/users", () => new HttpResponse(null, { status: 500 })))
  render(<UserList />)
  expect(await screen.findByText(/something went wrong/i)).toBeInTheDocument()
})

// network failure instead of an HTTP error
server.use(http.get("/api/users", () => HttpResponse.error()))

// avoid
await waitFor(() => {
  expect(screen.getByText("Saved")).toBeInTheDocument()
  expect(onSave).toHaveBeenCalledTimes(1)
})

// prefer: wait for one thing, then assert the rest synchronously
expect(await screen.findByText("Saved")).toBeInTheDocument()
expect(onSave).toHaveBeenCalledTimes(1)

it("increments the counter", () => {
  const { result } = renderHook(() => useCounter(0))

  expect(result.current.count).toBe(0)

  act(() => result.current.increment())   // state updates must be wrapped

  expect(result.current.count).toBe(1)
})

